import React, { useState, useEffect, useCallback } from 'react'
import { useContexState } from '../hooks/context'

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
    }]
}

interface NumbersType {
    lineCards: number;
    id: string;
}

export function useLoadPage() {
    const [getList, setGetList] = useState<ConvertListReturn>();
    const [qwe, asd] = useState(0)

    const {
        loading,
        page,
        total,
        feed
    } = useContexState();

    const {
        setFeed,
        setLoading,
        setPage,
    } = useContexState();

    function convertList({ data }: ConvertListParam) {
        return data.reduce<any>((h, card) =>
            Object.assign(h, {
                [card.number]: (h[card.number] || [])
                    .concat(
                        {
                            id: card.id,
                            name: card.name,
                            phone: card.phone,
                            price: card.price,
                        })
            }), {}
        );
    };

    const [numb, setNumb] = useState([])


    function LoadPage(value: number | number = 0) {
        if (page === total) return;
        if (loading) return;

        setLoading(true);

        const perPage = 84;

        for (let i = 0; i < perPage; i++) {
            setNumb({...numb, ...{ lineCards: (i * 6) + value, id: String(i) }})
        }


        api.get("getCards", {
            params: {
                firstNumber: value,
                lastNumber: value + 200
            }
        }
        ).then((responce) => {
            console.log(JSON.stringify(responce.data));
            setGetList(convertList(responce))
        })


        setLoading(false);
        setPage(page + 1);
        setFeed([...numb])
    }

    return { LoadPage, getList }
}
